#!/usr/bin/env python3
"""Fetch Paul Graham essays and create an audiobook MP3."""

import os
import re
import html
import subprocess
from html.parser import HTMLParser


def fetch_html(url: str) -> str:
    result = subprocess.run(["curl", "-L", "-s", url], capture_output=True, text=True)
    if result.returncode != 0 or not result.stdout:
        raise RuntimeError(f"Failed to fetch {url}: {result.stderr.strip()}")
    return result.stdout


class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
        self.skip = False

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style", "noscript"):
            self.skip = True
        elif tag in ("p", "br", "hr", "div", "tr", "li", "h1", "h2", "h3", "h4", "h5", "h6"):
            self.parts.append("\n")

    def handle_endtag(self, tag):
        if tag in ("script", "style", "noscript"):
            self.skip = False
        elif tag in ("p", "br", "hr", "div", "tr", "li", "h1", "h2", "h3", "h4", "h5", "h6"):
            self.parts.append("\n")

    def handle_data(self, data):
        if not self.skip:
            self.parts.append(data)


def html_to_text(html_content: str) -> str:
    parser = TextExtractor()
    parser.feed(html_content)
    text = "".join(parser.parts)
    text = html.unescape(text)
    return text


def clean_text_for_tts(text: str) -> str:
    text = re.sub(r"http[s]?://\S+", "", text)
    text = re.sub(r"\[\d+\]", "", text)
    text = re.sub(r"\s+", " ", text)
    text = re.sub(r"[^\w\s.,!?;:'\"()\-]", "", text)
    return text.strip()


def verify_content(text: str, expected_min_chars: int = 2000) -> bool:
    if len(text) < expected_min_chars:
        print(f"WARNING: Content may be truncated ({len(text)} chars)")
        return False
    if "summary" in text.lower()[:500] or "key points" in text.lower()[:500]:
        print("WARNING: Content appears to be a summary, not full text")
        return False
    return True


def chunk_text(text: str, max_chars: int = 4000):
    sentences = re.split(r"(?<=[.!?])\s+", text)
    chunks = []
    current = ""
    for sentence in sentences:
        if len(current) + len(sentence) + 1 < max_chars:
            current += sentence + " "
        else:
            if current:
                chunks.append(current.strip())
            current = sentence + " "
    if current:
        chunks.append(current.strip())
    return chunks


def concatenate_audio(audio_files, output_path):
    if not audio_files:
        return False

    list_file = "/tmp/audio_list.txt"
    with open(list_file, "w", encoding="utf-8") as f:
        for audio_file in audio_files:
            f.write(f"file '{audio_file}'\n")

    result = subprocess.run([
        "ffmpeg", "-y", "-f", "concat", "-safe", "0",
        "-i", list_file, "-c", "copy", output_path
    ], capture_output=True)

    for fpath in audio_files:
        try:
            os.unlink(fpath)
        except FileNotFoundError:
            pass
    try:
        os.unlink(list_file)
    except FileNotFoundError:
        pass

    if result.returncode != 0:
        print(result.stderr.decode("utf-8", errors="ignore"))
    return result.returncode == 0


def create_with_elevenlabs(text, output_path):
    import requests

    api_key = os.environ.get("ELEVENLABS_API_KEY")
    voice_id = "21m00Tcm4TlvDq8ikWAM"  # Rachel

    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        response = requests.post(
            f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
            headers={
                "xi-api-key": api_key,
                "Content-Type": "application/json",
            },
            json={
                "text": chunk,
                "model_id": "eleven_turbo_v2_5",
                "voice_settings": {"stability": 0.5, "similarity_boost": 0.75},
            },
            timeout=60,
        )
        if response.status_code == 200:
            with open(chunk_file, "wb") as f:
                f.write(response.content)
            audio_files.append(chunk_file)
            print(f"ElevenLabs chunk {i+1}/{len(chunks)} done")
        else:
            print(f"Error: {response.status_code} - {response.text}")
            return False

    return concatenate_audio(audio_files, output_path)


def create_with_openai(text, output_path):
    import requests

    api_key = os.environ.get("OPENAI_API_KEY")
    chunks = chunk_text(text, max_chars=4000)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        response = requests.post(
            "https://api.openai.com/v1/audio/speech",
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
            },
            json={
                "model": "tts-1",
                "input": chunk,
                "voice": "onyx",
                "response_format": "mp3",
            },
            timeout=60,
        )
        if response.status_code == 200:
            with open(chunk_file, "wb") as f:
                f.write(response.content)
            audio_files.append(chunk_file)
            print(f"OpenAI chunk {i+1}/{len(chunks)} done")
        else:
            print(f"Error: {response.status_code} - {response.text}")
            return False

    return concatenate_audio(audio_files, output_path)


def create_with_gtts(text, output_path):
    from gtts import gTTS

    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        tts = gTTS(text=chunk, lang="en", slow=False)
        tts.save(chunk_file)
        audio_files.append(chunk_file)
        print(f"gTTS chunk {i+1}/{len(chunks)} done")

    return concatenate_audio(audio_files, output_path)


def create_audiobook(text, output_path):
    has_elevenlabs = bool(os.environ.get("ELEVENLABS_API_KEY"))
    has_openai = bool(os.environ.get("OPENAI_API_KEY"))

    if has_elevenlabs:
        print("Using ElevenLabs TTS")
        return create_with_elevenlabs(text, output_path)
    if has_openai:
        print("Using OpenAI TTS")
        return create_with_openai(text, output_path)

    print("Using gTTS fallback")
    return create_with_gtts(text, output_path)


def main():
    urls = [
        "https://paulgraham.com/ds.html",
        "https://paulgraham.com/foundermode.html",
    ]

    sections = []

    for url in urls:
        print(f"Fetching: {url}")
        html_content = fetch_html(url)
        text = html_to_text(html_content)

        if not verify_content(text):
            print(f"WARNING: Content from {url} may be incomplete")

        sections.append(text)

    combined = (
        "Essay: Do Things that Don't Scale. By Paul Graham. "
        + sections[0]
        + " End of essay. "
        + "Essay: Founder Mode. By Paul Graham. "
        + sections[1]
        + " End of essay."
    )

    clean_text = clean_text_for_tts(combined)
    print(f"Total cleaned text length: {len(clean_text)} chars")

    success = create_audiobook(clean_text, "/root/audiobook.mp3")

    if success:
        print("Audiobook created: /root/audiobook.mp3")
    else:
        raise SystemExit("Failed to create audiobook")


if __name__ == "__main__":
    main()
